import{_ as e,o,c as s,a2 as a}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"通知","description":"","frontmatter":{},"headers":[],"relativePath":"guide/notify.md","filePath":"guide/notify.md","lastUpdated":1794726253000}'),d={name:"guide/notify.md"};function i(n,t,r,l,h,c){return o(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h1><p>在 <strong>网站配置 → 通知</strong> 里填写 Telegram 机器人或 Webhook 地址（两个都填就都发），打开 <strong>启用通知</strong> 后保存。点 <strong>发送测试</strong> 可以先用当前填写的内容试发一条，不用先保存。</p><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事件</th><th>什么时候提醒</th></tr></thead><tbody><tr><td>节点掉线 / 恢复</td><td>节点断开超过 90 秒才提醒，重启、升级等短暂断线不打扰；重新连上后再发一条恢复</td></tr><tr><td>导入节点连不上 / 恢复</td><td><a href="./import#连通性检测">连通性检测</a> 连续两次失败（约 6 分钟）才提醒，恢复后再发一条</td></tr><tr><td>内核运行出错</td><td>节点上的 Xray / sing-box 状态变成出错时提醒，附带错误信息</td></tr><tr><td>延迟 / 丢包异常 / 恢复</td><td>节点到某个测试点连续 3 轮探测劣化（丢包率或延迟达到阈值）时提醒一次，恢复后再发一条</td></tr><tr><td>回程线路变化</td><td>节点的回程线路识别结果与上次相比发生变化时提醒（IPv6 线路变化单独一行）</td></tr><tr><td>节点即将到期</td><td>节点设置了到期时间，到期前 3 天内提醒一次（在节点页关掉到期提醒的节点不会提醒）</td></tr><tr><td>用户流量 / 到期</td><td>转发用户流量用到 90%、用完，或 3 天内到期；<a href="./subscription#流量上限">分享订阅</a> 流量用到 90%、用完，或 3 天内到期；用户<a href="./forward#日-月配额">日/月配额</a>用到 90%、用完时同样提醒，配额解除（窗口滚动或手动重置）后发一条恢复</td></tr><tr><td>每日汇总</td><td>每天在设定的时间发一条：节点在线数、内核出错数、导入节点连不上的数量、入站和转发流量、分享订阅情况、日/月配额超额用户数（无超额时不显示该行）。因无数据或查询失败而未列出的行会在文末统一补一行 <code>未列出：行（原因）、…</code>（例如 <code>未列出：节点在线（无节点）、内核出错（无内核记录）</code>）；没有任何行可列时正文只有 <code>暂无数据</code> 加这一行</td></tr><tr><td>连接跟踪表用量过高</td><td>节点 conntrack 表用量达 80% 时提醒，表满后内核丢弃全部新数据包；回落到 70% 以下解除并重新武装</td></tr><tr><td>磁盘用量过高</td><td>节点或面板根盘用量达 80% 时提醒；回落到 70% 以下解除并重新武装</td></tr><tr><td>agent 内存用量过高</td><td>节点 agent 进程内存（RSS）用量达整机内存 80% 时提醒；回落到 70% 以下解除并重新武装</td></tr></tbody></table><p>同一个问题只提醒一次，恢复后才会再次提醒。不想收的事件取消勾选即可。全部取消时，后端会把事件配置 <code>none</code> 视为&quot;不启用任何事件&quot;（O8-006 兼容说明：旧版本前端就是靠这个字面量表示全不选的）。</p><p>表末三项资源告警（连接跟踪表 / 磁盘 / agent 内存）有<strong>独立开关</strong>（通知设置里的「资源告警」区，配置键 <code>notify_conntrack_high</code> / <code>notify_disk_high</code> / <code>notify_agent_memory_high</code>，缺省开启）：它们不走上方事件勾选——取消任一事件、乃至全部取消（<code>none</code>），都不会关掉资源告警；要停用某项资源告警，取消它自己的勾选。只有关掉 <strong>启用通知</strong> 总开关才会停掉全部通知。</p><p>面板重启后，之前已掉线的节点会在启动扫描时补发一条&quot;面板重启后仍离线&quot;，不会因为重启而漏报。发送失败的通知会在单次发送内按通道分别重试一次；仍然失败的<strong>不会记为已发送</strong>，会在后续检查中补发（每日汇总同理，在同一小时内的后续检查中补发）。补发只补未送达的通道：通道级送达台账已落地且为全部事件共用，正常运行时发送失败只补发未成功送达的通道，已经成功的通道不会重复收到。需要注意的是，台账为进程内存态：若在部分通道已送达、其余待补发期间重启面板，待发状态会丢失并按最新累计值重算重发，已送达通道可能多收一份重算版日报，其余事件同理可能多收一份原文。</p><p>每日汇总默认早上 9 点发送，可以在 <strong>每日汇总发送时间</strong> 里改（0–23 点）。时间按面板服务器的时区，安装脚本默认 <code>Asia/Shanghai</code>。</p><h3 id="延迟-丢包阈值" tabindex="-1">延迟 / 丢包阈值 <a class="header-anchor" href="#延迟-丢包阈值" aria-label="Permalink to &quot;延迟 / 丢包阈值&quot;">​</a></h3><p>在 <strong>网站配置 → 通知</strong> 里勾选 <strong>延迟 / 丢包异常</strong> 事件后，下方会展开 <strong>延迟 / 丢包阈值</strong> 字段组。两个字段都填整数：</p><table tabindex="0"><thead><tr><th>字段</th><th>配置键</th><th>填法</th><th>留空时</th></tr></thead><tbody><tr><td>丢包率 ≥（%）</td><td><code>notify_latency_loss_pct</code></td><td>整数 1–100</td><td>默认 20</td></tr><tr><td>延迟 ≥（ms）</td><td><code>notify_latency_ms</code></td><td>整数，大于 0 才启用延迟判断</td><td>0＝不判断</td></tr></tbody></table><ul><li><strong>触发口径</strong>：节点到某个测试点**连续 3 次检测（约 9 分钟）**丢包率 ≥ 阈值，或（延迟判断已启用时）延迟 ≥ 阈值，判为劣化并提醒一条，恢复后再发一条；测试点连不上直接算劣化，不看阈值。</li><li><strong>防错</strong>：延迟填 <code>0</code> 不是「延迟 ≥ 0 就报」，而是<strong>关闭延迟判断</strong>；丢包率填 <code>0</code>、超过 100 或填非整数，都不会按字面值生效，而是当作未设置、回落默认 20%。改完点保存，之后每轮检测都按新值判断。</li><li><strong>自检</strong>：把延迟阈值临时改成 <code>1</code> 保存，正常节点也会在约 9 分钟后收到一条延迟异常提醒；确认收到后改回需要的数值（或清空恢复默认）。</li></ul><h2 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h2><ol><li>找 <a href="https://t.me/BotFather" target="_blank" rel="noreferrer">@BotFather</a> 发 <code>/newbot</code> 创建机器人，拿到 Bot Token（形如 <code>123456:ABC-DEF...</code>）</li><li>给你的机器人发一条消息（或把它拉进群），再用 <a href="https://t.me/userinfobot" target="_blank" rel="noreferrer">@userinfobot</a> 查自己的 Chat ID；群组的 ID 以 <code>-100</code> 开头</li><li>在 <strong>网站配置 → 通知</strong> 里把 Bot Token 填入 <strong>Telegram Bot Token</strong> 字段、Chat ID 填入 <strong>Telegram Chat ID</strong> 字段，点 <strong>发送测试</strong> 验证</li></ol><blockquote><p>Bot Token 等同机器人的钥匙：泄露后任何人都能冒充你的机器人发消息。怀疑泄露时在 BotFather 里发 <code>/revoke</code> 作废旧 Token 并换新，再回面板更新 <strong>Telegram Bot Token</strong> 字段。</p></blockquote><p>面板服务器在国内、连不上 <code>api.telegram.org</code> 时，可以在 <strong>Telegram API 地址</strong> 里填一个反代地址（例如 Cloudflare Workers 反代），面板会请求 <code>&lt;地址&gt;/bot&lt;Token&gt;/sendMessage</code>。</p><h3 id="机器人菜单-自主查询" tabindex="-1">机器人菜单（自主查询） <a class="header-anchor" href="#机器人菜单-自主查询" aria-label="Permalink to &quot;机器人菜单（自主查询）&quot;">​</a></h3><p>配好 Telegram 后，机器人除了收通知，还能主动查：在 Telegram 里给机器人发 <code>/start</code>，会弹出三个按钮——<strong>🖥 节点状态</strong>、<strong>📊 流量</strong>、<strong>ℹ️ 面板状态</strong>；也可以直接发 <code>/nodes</code>、<code>/traffic</code>、<code>/status</code> 得到同样的回答（这四个命令已在 Telegram 的命令菜单里注册）。</p><ul><li><strong>节点状态</strong>：全部节点逐个列出，在线的标 🟢 并附最近 15 分钟内的探针延迟（过期或无探针时不显示），离线的标 🔴；末尾汇总总数与在线数。</li><li><strong>流量</strong>：今日＝自 0 点以来整点增量合计（当前不足一小时的部分未计入）；本周期＝用户流量快照合计，按月重置。</li><li><strong>面板状态</strong>：面板版本、节点总数/在线数、已运行时间。</li></ul><p>只有 <strong>Telegram Chat ID</strong> 里填的那个聊天能用：别的聊天发来的消息和点的按钮一律静默忽略，不回复。通知总开关关掉时机器人菜单也不工作（轮询休眠），先打开 <strong>启用通知</strong>。机器人只回答这三个查询，其他文字一律忽略。</p><h2 id="webhook" tabindex="-1">Webhook <a class="header-anchor" href="#webhook" aria-label="Permalink to &quot;Webhook&quot;">​</a></h2><p>面板会向填写的地址发送 <code>POST</code> 请求，内容是 JSON：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node_offline&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;节点掉线&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;节点：东京-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;🔴 &lt;b&gt;节点掉线&lt;/b&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">节点：东京-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">🕐 2026-10-16 18:00:00 +08:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;time&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1792144800000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FLMX&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>event</code>：<code>node_offline</code>、<code>node_upgrade_failed</code>（节点升级/回退下发后超时未回连到目标版本）、<code>nft_collect_failed</code>（节点 nft 流量采集连续失败 3 轮约 90 秒，恢复时再发一次）、<code>inbound_down</code>、<code>kernel_error</code>、<code>node_expiry</code>、<code>user_quota</code>、<code>daily_report</code>、<code>latency_bad</code>（延迟/丢包异常与恢复）、<code>route_change</code>（回程线路变化）、<code>conntrack_high</code>（节点连接跟踪表用量达 80%）、<code>disk_high</code>（节点或面板磁盘用量达 80%）、<code>agent_memory_high</code>（节点 agent 内存用量达 80%），测试消息是 <code>test</code></li><li><code>text</code>：与 Telegram 共用同一 HTML 渲染的完整文本——emoji ＋ <code>&lt;b&gt;标题&lt;/b&gt;</code> ＋ 正文 ＋ <code>🕐</code> 数字时区偏移页脚（旧纯文本格式的 <code>[FLMX]</code> 前缀已去掉，也没有单独的 <code>时间：… UTC</code> 行，时间在 <code>🕐</code> 页脚里）。直接转发给企业微信、钉钉、Bark、Server 酱等纯文本渠道时，对方会原样收到 <code>&lt;b&gt;</code> 标签；需要纯文本时先去掉 HTML 标签，或改用 <code>message</code> 字段自己拼</li><li><code>time</code>：毫秒级 Unix 时间戳（数字，不是格式化字符串）；带时区的格式化时间在 <code>text</code> 字段里</li><li>返回 2xx 视为发送成功</li><li>出站地址口径：以下硬拒集会被明确拒绝——云元数据精确地址 3 个（<code>169.254.169.254</code>、<code>100.100.100.200</code> 阿里云元数据、<code>fd00:ec2::254</code> AWS IPv6 元数据）、<code>169.254.0.0/16</code> 链路本地段整段、未指定地址（<code>0.0.0.0</code>、<code>::</code>）；除此之外内网地址默认放行——把 Webhook 发到内网的企业微信/告警网关是预期用法</li></ul><p>Bot Token 和 Webhook 地址保存后<strong>任何角色（含管理员）都无法读回</strong>（配置页不回显、读接口不返回明文），也不会写进 JSON 备份。</p>`,25)])])}const k=e(d,[["render",i]]);export{p as __pageData,k as default};
